def f(h):
	if h == 1:
		return 1
	elif h == 2:
		return 1
	else:
		a = 1
		b = 1
		for i in range(h - 2):
			c = a + b
			a = b
			b = c
		return b
for _ in range(int(input())):
	(m, n) = map(int, input().split())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	w = sum(a)
	e = sum(b)
	y = 10 ** 9 + 7
	ans = m * ((f(n - 2) % y * (w % y) % y + f(n - 1) % y * (e % y) % y) % y) % y
	if n == 1:
